{"name": "matrix_power_mod", "code": "import numpy as np
def solve(inputs: dict) -> float:
    A, B, C, D, MOD, K = inputs['A'], inputs['B'], inputs['C'], inputs['D'], inputs['MOD'], inputs['K']\n    M = np.array([[A, B], [C, D]], dtype=object)
    def matrix_mod(X, Y):
        return (X @ Y) % MOD
    result_matrix = np.identity(2, dtype=object)
    current_matrix = M
    while K > 0:
        if K % 2 == 1:
            result_matrix = matrix_mod(result_matrix, current_matrix)
        current_matrix = matrix_mod(current_matrix, current_matrix)
        K //= 2
    return np.sum(result_matrix) % MOD"}
